nding patients retrieved');\n   53 |     \n   54 | } catch (\\Exception $e) {\n   55 |     error_log('Get pending patients error: ' . $e->getMessage());\n   56 |     errorResponse('Failed to fetch pending patients', 500);\n   57 | }\n   58 |",
