ole === \"registrar\" ||\n   39 |     isConsultantType(role) ||\n   40 |     role === \"admin\"\n   41 |   );\n   42 | }\n   43 | \n   44 | export const STAFF_ROLE_LABELS: Record<\n   45 |   Exclude<StaffRole, \"admin\" | \"patient\" | \"doctor\">,\n   46 |   string\n   47 | > = {\n   48 |   consultant_doctor: \"Consultant Doctor\",\n   49 |   medical_officer: \"Medical Officer\",\n   50 |   intern_doctor: \"Intern Doctor\",\n   51 |   nurse: \"Nurse\",\n   52 |   staff: \"Staff \/ Reception\",\n   53 |   reception: \"Reception \/ Front Desk\",\n   54 |   assistant_registrar: \"Assistant Registrar\",\n   55 |   registrar: \"Registrar\",\n   56 |   assistant_professor: \"Assistant Professor\",\n   57 |   associate_professor: \"Associate Professor\",\n   58 |   professor: \"Professor\",\n   59 | };\n   60 | \n   61 | \/** Ordered hierarchy for display (lowest \u2192 highest) *\/\n   62 | export const ROLE_HIERARCHY_ORDER: Exclude<StaffRole, \"admin\" | \"patient\">[] = [\n   63 |   \"nurse\",\n   64 |   \"intern_doctor\",\n   65 |   \"medical_officer\",\n   66 |   \"assistant_registrar\",\n   67 |   \"registrar\",\n   68 |   \"consultant_doctor\",\n   69 |   \"assistant_professor\",\n   70 |   \"associate_professor\",\n   71 |   \"professor\",\n   72 |   \"staff\",\n   73 | ];\n   74 | \n   75 | export const STAFF_ROLE_COLORS: Record<\n   76 |   Exclude<StaffRole, \"admin\" | \"patient\">,\n   77 |   string\n   78 | > = {\n   79 |   consultant_doctor: \"bg-blue-700 text-white border-blue-700\",\n   80 |   medical_officer: \"bg-teal-600 text-white border-teal-600\",\n   81 |   intern_doctor: \"bg-violet-600 text-white border-violet-600\",\n   82 |   nurse: \"bg-rose-600 text-white border-rose-600\",\n   83 |   staff: \"bg-amber-600 text-white border-amber-600\",\n   84 |   reception: \"bg-amber-600 text-white border-amber-600\",\n   85 |   doctor: \"bg-emerald-600 text-white border-emerald-600\",\n   86 |   assistant_registrar: \"bg-emerald-500 text-white border-emeral